/* Russian (RU) translation data + generic templates for the /ru/ site — Phase 2/3
   (2026-09-14, see wiki/log.md same date). Loaded as a plain browser global (RU pages, via
   js/main.js's RU branches) AND via the same Node vm sandbox used by scripts/lib/site-data.js's
   loadGlobals() (scripts/build-product-pages-ru.js, scripts/build-hub-pages-ru.js) — keep it
   free of browser-only APIs (no `document`/`window`), same rule as js/faq-templates.js.

   Structure mirrors js/data.js + js/faq-templates.js 1:1 so EN/RU logic stays in lockstep:
     - CATEGORIES_RU / STATUS_LABEL_RU / COUNTRY_RU — translated versions of the small EN dicts
     - PRODUCT_SPEC_RU — model -> translated one-line `spec` string, all 82 SKUs
     - PRODUCT_DEEP_RU — model -> translated {specs, applications, compatibility, faq} for the
       6 SKUs that have hand-written deep content in js/data.js (p.specs/applications/faq present)
     - genericFaqFor_ru()/genericApplicationsFor_ru() — RU port of js/faq-templates.js, used for
       the other 76 "standard page" SKUs, same genuine/non-genuine + status branching as the EN
       version (reads NON_GENUINE_BRANDS from js/data.js, same set for both languages)
     - UI_RU + ruPlural() — microcopy dictionary + Russian noun-pluralization helper for the
       dynamically-assembled strings in js/main.js and the RU build scripts (breadcrumbs, meta
       descriptions, spec-table labels, pagination, catalog result counts, hub-page templates) */

/* ---- Russian plural forms: n=1 -> forms[0], n=2..4 -> forms[1], else -> forms[2].
   Standard Russian count-noun agreement (товар/товара/товаров, модель/модели/моделей, etc). */
function ruPlural(n, forms) {
  n = Math.abs(n) % 100;
  const n1 = n % 10;
  if (n > 10 && n < 20) return forms[2];
  if (n1 > 1 && n1 < 5) return forms[1];
  if (n1 === 1) return forms[0];
  return forms[2];
}

